109	impl WindowsPlatform {
110	    pub fn new(headless: bool) -> Result<Self> {
111	        unsafe {
112	            OleInitialize(None).context("unable to initialize Windows OLE")?;
113	        }
114	        let (directx_devices, text_system, direct_write_text_system) = if !headless {
115	            let devices = DirectXDevices::new().context("Creating DirectX devices")?;
116	            let dw_text_system = Arc::new(
117	                DirectWriteTextSystem::new(&devices)
118	                    .context("Error creating DirectWriteTextSystem")?,
119	            );
120	            (
121	                Some(devices),
122	                dw_text_system.clone() as Arc<dyn PlatformTextSystem>,
123	                Some(dw_text_system),
124	            )
125	        } else {
126	            (
127	                None,
128	                Arc::new(gpui::NoopTextSystem::new()) as Arc<dyn PlatformTextSystem>,
129	                None,
130	            )
131	        };
132	
133	        let (main_sender, main_receiver) = PriorityQueueReceiver::new();
134	        let validation_number = if usize::BITS == 64 {
135	            rand::random::<u64>() as usize
136	        } else {
137	            rand::random::<u32>() as usize
138	        };
139	        let raw_window_handles = Arc::new(RwLock::new(SmallVec::new()));
140	
141	        register_platform_window_class();
142	        let mut context = PlatformWindowCreateContext {
143	            inner: None,
144	            raw_window_handles: Arc::downgrade(&raw_window_handles),
145	            validation_number,
146	            main_sender: Some(main_sender),
147	            main_receiver: Some(main_receiver),
148	            directx_devices,
149	            dispatcher: None,
150	        };
151	        let result = unsafe {
152	            CreateWindowExW(
153	                WINDOW_EX_STYLE(0),
154	                PLATFORM_WINDOW_CLASS_NAME,
155	                None,
156	                WINDOW_STYLE(0),
157	                0,
158	                0,
159	                0,
160	                0,
161	                Some(HWND_MESSAGE),
162	                None,
163	                None,
164	                Some(&raw const context as *const _),
165	            )
166	        };
167	        let inner = context
168	            .inner
169	            .take()
170	            .context("CreateWindowExW did not run correctly")??;
171	        let dispatcher = context
172	            .dispatcher
173	            .take()
174	            .context("CreateWindowExW did not run correctly")?;
175	        let handle = result?;
176	
177	        let disable_direct_composition = std::env::var(DISABLE_DIRECT_COMPOSITION)
178	            .is_ok_and(|value| value == "true" || value == "1");
179	        let background_executor = BackgroundExecutor::new(dispatcher.clone());
180	        let foreground_executor = ForegroundExecutor::new(dispatcher);
181	
182	        let drop_target_helper: Option<IDropTargetHelper> = if !headless {
183	            Some(unsafe {
184	                CoCreateInstance(&CLSID_DragDropHelper, None, CLSCTX_INPROC_SERVER)
185	                    .context("Error creating drop target helper.")?
186	            })
187	        } else {
188	            None
189	        };
190	        let icon = if !headless {
191	            load_icon().unwrap_or_default()
192	        } else {
193	            HICON::default()
194	        };
195	
196	        Ok(Self {
197	            inner,
198	            handle,
199	            raw_window_handles,
200	            headless,
201	            icon,
202	            background_executor,
203	            foreground_executor,
204	            text_system,
205	            direct_write_text_system,
206	            suspend_resume_notification: RefCell::new(None),
207	            disable_direct_composition,
