312	    fn begin_vsync_thread(&self) {
313	        let Some(directx_devices) = self.inner.state.directx_devices.borrow().clone() else {
314	            return;
315	        };
316	        let Some(direct_write_text_system) = &self.direct_write_text_system else {
317	            return;
318	        };
319	        let mut directx_device = directx_devices;
320	        let platform_window: SafeHwnd = self.handle.into();
321	        let validation_number = self.inner.validation_number;
322	        let all_windows = Arc::downgrade(&self.raw_window_handles);
323	        let text_system = Arc::downgrade(direct_write_text_system);
324	        let invalidate_devices = self.invalidate_devices.clone();
325	
326	        std::thread::Builder::new()
327	            .name("VSyncProvider".to_owned())
328	            .spawn(move || {
329	                let vsync_provider = VSyncProvider::new();
330	                loop {
331	                    vsync_provider.wait_for_vsync();
332	                    if check_device_lost(&directx_device.device)
333	                        || invalidate_devices.fetch_and(false, Ordering::Acquire)
334	                    {
335	                        if let Err(err) = handle_gpu_device_lost(
336	                            &mut directx_device,
337	                            platform_window.as_raw(),
338	                            validation_number,
339	                            &all_windows,
340	                            &text_system,
341	                        ) {
342	                            panic!("Device lost: {err}");
343	                        }
344	                    }
345	                    let Some(all_windows) = all_windows.upgrade() else {
346	                        break;
347	                    };
348	                    for hwnd in all_windows.read().iter() {
349	                        unsafe {
350	                            let _ = RedrawWindow(Some(hwnd.as_raw()), None, None, RDW_INVALIDATE);
351	                        }
352	                    }
353	                }
354	            })
355	            .unwrap();
356	    }
357	}
