359	fn translate_accelerator(msg: &MSG) -> Option<()> {
360	    if msg.message != WM_KEYDOWN && msg.message != WM_SYSKEYDOWN {
361	        return None;
362	    }
363	
364	    let result = unsafe {
365	        SendMessageW(
366	            msg.hwnd,
367	            WM_GPUI_KEYDOWN,
368	            Some(msg.wParam),
369	            Some(msg.lParam),
370	        )
371	    };
372	    (result.0 == 0).then_some(())
373	}
