447	    fn run(&self, on_finish_launching: Box<dyn 'static + FnOnce()>) {
448	        on_finish_launching();
449	        if !self.headless {
450	            self.begin_vsync_thread();
451	        }
452	
453	        let mut msg = MSG::default();
454	        unsafe {
455	            while GetMessageW(&mut msg, None, 0, 0).as_bool() {
456	                if translate_accelerator(&msg).is_none() {
457	                    _ = TranslateMessage(&msg);
458	                    DispatchMessageW(&msg);
459	                }
460	            }
461	        }
462	
463	        self.inner
464	            .with_callback(|callbacks| &callbacks.quit, |callback| callback());
465	    }
