872	    fn read_credentials(&self, url: &str) -> Task<Result<Option<(String, Vec<u8>)>>> {
873	        let target_name = windows_credentials_target_name(url)
874	            .encode_utf16()
875	            .chain(Some(0))
876	            .collect_vec();
877	        self.foreground_executor().spawn(async move {
