975	    /// Calls `project` to project to the corresponding callback field, removes it from callbacks, calls `f` with the callback and then puts the callback back.
976	    fn with_callback<T>(
977	        &self,
978	        project: impl Fn(&PlatformCallbacks) -> &Cell<Option<T>>,
979	        f: impl FnOnce(&mut T),
980	    ) {
981	        let callback = project(&self.state.callbacks).take();
982	        if let Some(mut callback) = callback {
983	            f(&mut callback);
984	            project(&self.state.callbacks).set(Some(callback));
985	        }
986	    }
