1029	    fn close_one_window(&self, target_window: HWND) -> bool {
1030	        let Some(all_windows) = self.raw_window_handles.upgrade() else {
1031	            log::error!("Failed to upgrade raw window handles");
1032	            return false;
1033	        };
1034	        let mut lock = all_windows.write();
1035	        let index = lock
1036	            .iter()
1037	            .position(|handle| handle.as_raw() == target_window)
1038	            .unwrap();
