1044	    #[inline]
1045	    fn run_foreground_task(&self) -> Option<isize> {
1046	        const MAIN_TASK_TIMEOUT: u128 = 10;
1047	
1048	        let start = std::time::Instant::now();
1049	        'tasks: loop {
1050	            'timeout_loop: loop {
1051	                if start.elapsed().as_millis() >= MAIN_TASK_TIMEOUT {
1052	                    log::debug!("foreground task timeout reached");
1053	                    // we spent our budget on gpui tasks, we likely have a lot of work queued so drain system events first to stay responsive
1054	                    // then quit out of foreground work to allow us to process other gpui events first before returning back to foreground task work
1055	                    // if we don't we might not for example process window quit events
1056	                    let mut msg = MSG::default();
1057	                    let process_message = |msg: &_| {
1058	                        if translate_accelerator(msg).is_none() {
1059	                            _ = unsafe { TranslateMessage(msg) };
1060	                            unsafe { DispatchMessageW(msg) };
1061	                        }
1062	                    };
1063	                    let peek_msg = |msg: &mut _, msg_kind| unsafe {
1064	                        PeekMessageW(msg, None, 0, 0, PM_REMOVE | msg_kind).as_bool()
1065	                    };
1066	                    // We need to process a paint message here as otherwise we will re-enter `run_foreground_task` before painting if we have work remaining.
1067	                    // The reason for this is that windows prefers custom application message processing over system messages.
1068	                    if peek_msg(&mut msg, PM_QS_PAINT) {
1069	                        process_message(&msg);
1070	                    }
1071	                    while peek_msg(&mut msg, PM_QS_INPUT) {
1072	                        process_message(&msg);
1073	                    }
1074	                    // Allow the main loop to process other gpui events before going back into `run_foreground_task`
1075	                    unsafe {
1076	                        if let Err(_) = PostMessageW(
1077	                            Some(self.dispatcher.platform_window_handle.as_raw()),
1078	                            WM_GPUI_TASK_DISPATCHED_ON_MAIN_THREAD,
1079	                            WPARAM(self.validation_number),
1080	                            LPARAM(0),
1081	                        ) {
1082	                            self.dispatcher.wake_posted.store(false, Ordering::Release);
1083	                        };
1084	                    }
1085	                    break 'tasks;
1086	                }
1087	                let mut main_receiver = self.main_receiver.clone();
1088	                match main_receiver.try_pop() {
1089	                    Ok(Some(runnable)) => WindowsDispatcher::execute_runnable(runnable),
1090	                    _ => break 'timeout_loop,
1091	                }
1092	            }
1093	
1094	            // Someone could enqueue a Runnable here. The flag is still true, so they will not PostMessage.
1095	            // We need to check for those Runnables after we clear the flag.
1096	            self.dispatcher.wake_posted.store(false, Ordering::Release);
1097	            let mut main_receiver = self.main_receiver.clone();
1098	            match main_receiver.try_pop() {
1099	                Ok(Some(runnable)) => {
1100	                    self.dispatcher.wake_posted.store(true, Ordering::Release);
1101	
1102	                    WindowsDispatcher::execute_runnable(runnable);
1103	                }
1104	                _ => break 'tasks,
1105	            }
1106	        }
1107	
1108	        Some(0)
1109	    }
