1280	    options: PathPromptOptions,
1281	    window: Option<HWND>,
1282	) -> Result<Option<Vec<PathBuf>>> {
1283	    let folder_dialog: IFileOpenDialog =
1284	        unsafe { CoCreateInstance(&FileOpenDialog, None, CLSCTX_ALL)? };
1285	
1286	    let mut dialog_options = FOS_FILEMUSTEXIST;
1287	    if options.multiple {
1288	        dialog_options |= FOS_ALLOWMULTISELECT;
1289	    }
1290	    if options.directories {
1291	        dialog_options |= FOS_PICKFOLDERS;
1292	    }
1293	
1294	    unsafe {
1295	        folder_dialog.SetOptions(dialog_options)?;
1296	
1297	        if let Some(prompt) = options.prompt {
1298	            let prompt: &str = &prompt;
1299	            folder_dialog.SetOkButtonLabel(&HSTRING::from(prompt))?;
1300	        }
1301	
1302	        if folder_dialog.Show(window).is_err() {
1303	            // User cancelled
1304	            return Ok(None);
1305	        }
1306	    }
1307	
1308	    let results = unsafe { folder_dialog.GetResults()? };
1309	    let file_count = unsafe { results.GetCount()? };
1310	    if file_count == 0 {
1311	        return Ok(None);
1312	    }
1313	
1314	    let mut paths = Vec::with_capacity(file_count as usize);
1315	    for i in 0..file_count {
1316	        let item = unsafe { results.GetItemAt(i)? };
1317	        let path = unsafe { item.GetDisplayName(SIGDN_FILESYSPATH)?.to_string()? };
1318	        paths.push(PathBuf::from(path));
1319	    }
1320	
1321	    Ok(Some(paths))
1322	}
