274	            self.resources.take();
275	            if let Some(devices) = &self.devices {
276	                devices.device_context.OMSetRenderTargets(None, None);
277	                devices.device_context.ClearState();
278	                devices.device_context.Flush();
279	                #[cfg(debug_assertions)]
280	                report_live_objects(&devices.device)
281	                    .context("Failed to report live objects after device lost")
282	                    .log_err();
283	            }
284	
285	            self.direct_composition.take();
286	            self.devices.take();
287	        }
288	
289	        let devices = DirectXRendererDevices::new(directx_devices, disable_direct_composition)
290	            .context("Recreating DirectX devices")?;
291	        let resources = DirectXResources::new(
292	            &devices,
293	            self.width,
294	            self.height,
295	            self.hwnd,
296	            disable_direct_composition,
297	        )
298	        .context("Creating DirectX resources")?;
299	        let globals = DirectXGlobalElements::new(&devices.device)
300	            .context("Creating DirectXGlobalElements")?;
301	        let pipelines = DirectXRenderPipelines::new(&devices.device)
302	            .context("Creating DirectXRenderPipelines")?;
303	
304	        let direct_composition = if disable_direct_composition {
305	            None
306	        } else {
307	            let composition =
308	                DirectComposition::new(devices.dxgi_device.as_ref().unwrap(), self.hwnd)?;
309	            composition.set_swap_chain(&resources.swap_chain)?;
310	            Some(composition)
311	        };
312	
313	        self.atlas
314	            .handle_device_lost(&devices.device, &devices.device_context);
315	
316	        unsafe {
317	            devices
318	                .device_context
319	                .OMSetRenderTargets(Some(slice::from_ref(&resources.render_target_view)), None);
320	        }
321	        self.devices = Some(devices);
322	        self.resources = Some(resources);
323	        self.globals = globals;
324	        self.pipelines = pipelines;
325	        self.direct_composition = direct_composition;
326	        self.skip_draws = true;
327	        Ok(())
328	    }
