330	    pub(crate) fn draw(
331	        &mut self,
332	        scene: &Scene,
333	        background_appearance: WindowBackgroundAppearance,
334	    ) -> Result<()> {
335	        if self.skip_draws {
336	            // skip drawing this frame, we just recovered from a device lost event
337	            // and so likely do not have the textures anymore that are required for drawing
338	            return Ok(());
339	        }
340	        self.pre_draw(&match background_appearance {
341	            WindowBackgroundAppearance::Opaque => [1.0f32; 4],
342	            _ => [0.0f32; 4],
343	        })?;
344	
345	        self.upload_scene_buffers(scene)?;
346	
347	        let annotation = self
348	            .devices
349	            .as_ref()
350	            .and_then(|devices| devices.annotation.clone())
351	            .filter(|annotation| unsafe { annotation.GetStatus().as_bool() });
352	        for batch in scene.batches() {
353	            let _annotation = annotation
354	                .as_ref()
355	                .map(|annotation| Annotation::new(annotation, HSTRING::from(batch.label())));
356	            match batch {
357	                PrimitiveBatch::Shadows(range) => self.draw_shadows(range.start, range.len()),
358	                PrimitiveBatch::Quads(range) => self.draw_quads(range.start, range.len()),
359	                PrimitiveBatch::Paths(range) => {
360	                    let paths = &scene.paths[range];
361	                    self.draw_paths_to_intermediate(paths)?;
362	                    self.draw_paths_from_intermediate(paths)
363	                }
364	                PrimitiveBatch::Underlines(range) => self.draw_underlines(range.start, range.len()),
365	                PrimitiveBatch::MonochromeSprites { texture_id, range } => {
366	                    self.draw_monochrome_sprites(texture_id, range.start, range.len())
367	                }
368	                PrimitiveBatch::SubpixelSprites { texture_id, range } => {
369	                    self.draw_subpixel_sprites(texture_id, range.start, range.len())
370	                }
371	                PrimitiveBatch::PolychromeSprites { texture_id, range } => {
372	                    self.draw_polychrome_sprites(texture_id, range.start, range.len())
373	                }
374	                PrimitiveBatch::Surfaces(range) => self.draw_surfaces(&scene.surfaces[range]),
375	            }
376	            .with_context(|| {
377	                format!(
378	                    "scene too large:\
379	                    {} paths, {} shadows, {} quads, {} underlines, {} mono, {} subpixel, {} poly, {} surfaces",
380	                    scene.paths.len(),
381	                    scene.shadows.len(),
382	                    scene.quads.len(),
383	                    scene.underlines.len(),
384	                    scene.monochrome_sprites.len(),
385	                    scene.subpixel_sprites.len(),
386	                    scene.polychrome_sprites.len(),
387	                    scene.surfaces.len(),
388	                )
389	            })?;
390	        }
391	        self.present()
392	    }
