394	    pub(crate) fn resize(&mut self, new_size: Size<DevicePixels>) -> Result<()> {
395	        let width = new_size.width.0.max(1) as u32;
396	        let height = new_size.height.0.max(1) as u32;
397	        if self.width == width && self.height == height {
398	            return Ok(());
399	        }
400	        self.width = width;
401	        self.height = height;
402	
403	        // Clear the render target before resizing
404	        let devices = self.devices.as_ref().context("devices missing")?;
405	        unsafe { devices.device_context.OMSetRenderTargets(None, None) };
406	        let resources = self.resources.as_mut().context("resources missing")?;
407	        resources.render_target.take();
408	        resources.render_target_view.take();
409	
410	        // Resizing the swap chain requires a call to the underlying DXGI adapter, which can return the device removed error.
411	        // The app might have moved to a monitor that's attached to a different graphics device.
412	        // When a graphics device is removed or reset, the desktop resolution often changes, resulting in a window size change.
413	        // But here we just return the error, because we are handling device lost scenarios elsewhere.
414	        unsafe {
415	            resources
416	                .swap_chain
417	                .ResizeBuffers(
418	                    BUFFER_COUNT as u32,
419	                    width,
420	                    height,
421	                    RENDER_TARGET_FORMAT,
422	                    DXGI_SWAP_CHAIN_FLAG(0),
423	                )
424	                .context("Failed to resize swap chain")?;
425	        }
426	
427	        resources.recreate_resources(devices, width, height)?;
428	
429	        unsafe {
430	            devices
431	                .device_context
432	                .OMSetRenderTargets(Some(slice::from_ref(&resources.render_target_view)), None);
433	        }
434	
435	        Ok(())
436	    }
