524	    fn draw_paths_to_intermediate(&mut self, paths: &[Path<ScaledPixels>]) -> Result<()> {
525	        if paths.is_empty() {
526	            return Ok(());
527	        }
528	
529	        let devices = self.devices.as_ref().context("devices missing")?;
530	        let resources = self.resources.as_ref().context("resources missing")?;
531	        // Clear intermediate MSAA texture
532	        unsafe {
533	            devices.device_context.ClearRenderTargetView(
534	                resources.path_intermediate_msaa_view.as_ref().unwrap(),
535	                &[0.0; 4],
536	            );
537	            // Set intermediate MSAA texture as render target
538	            devices.device_context.OMSetRenderTargets(
539	                Some(slice::from_ref(&resources.path_intermediate_msaa_view)),
540	                None,
541	            );
542	        }
543	
544	        // Collect all vertices and sprites for a single draw call
545	        let mut vertices = Vec::new();
546	
547	        for path in paths {
548	            vertices.extend(path.vertices.iter().map(|v| PathRasterizationSprite {
549	                xy_position: v.xy_position,
550	                st_position: v.st_position,
551	                color: path.color,
552	                bounds: path.clipped_bounds(),
553	            }));
554	        }
555	
556	        self.pipelines.path_rasterization_pipeline.update_buffer(
557	            &devices.device,
558	            &devices.device_context,
559	            &vertices,
560	        )?;
561	
562	        self.pipelines.path_rasterization_pipeline.draw(
563	            &devices.device_context,
564	            D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST,
565	            vertices.len() as u32,
566	            1,
567	        )?;
568	
569	        // Resolve MSAA to non-MSAA intermediate texture
570	        unsafe {
571	            devices.device_context.ResolveSubresource(
572	                &resources.path_intermediate_texture,
573	                0,
574	                &resources.path_intermediate_msaa_texture,
575	                0,
576	                RENDER_TARGET_FORMAT,
577	            );
578	            // Restore main render target
579	            devices
580	                .device_context
581	                .OMSetRenderTargets(Some(slice::from_ref(&resources.render_target_view)), None);
582	        }
583	
584	        Ok(())
585	    }
586	
587	    fn draw_paths_from_intermediate(&mut self, paths: &[Path<ScaledPixels>]) -> Result<()> {
588	        let Some(first_path) = paths.first() else {
589	            return Ok(());
590	        };
591	
592	        // When copying paths from the intermediate texture to the drawable,
593	        // each pixel must only be copied once, in case of transparent paths.
594	        //
595	        // If all paths have the same draw order, then their bounds are all
596	        // disjoint, so we can copy each path's bounds individually. If this
597	        // batch combines different draw orders, we perform a single copy
598	        // for a minimal spanning rect.
599	        let sprites = if paths.last().unwrap().order == first_path.order {
600	            paths
601	                .iter()
602	                .map(|path| PathSprite {
603	                    bounds: path.clipped_bounds(),
604	                })
605	                .collect::<Vec<_>>()
606	        } else {
607	            let mut bounds = first_path.clipped_bounds();
608	            for path in paths.iter().skip(1) {
609	                bounds = bounds.union(&path.clipped_bounds());
610	            }
611	            vec![PathSprite { bounds }]
612	        };
613	
614	        let devices = self.devices.as_ref().context("devices missing")?;
615	        let resources = self.resources.as_ref().context("resources missing")?;
616	        self.pipelines.path_sprite_pipeline.update_buffer(
617	            &devices.device,
618	            &devices.device_context,
619	            &sprites,
620	        )?;
621	
622	        // Draw the sprites with the path texture
623	        self.pipelines.path_sprite_pipeline.draw_with_texture(
624	            &devices.device_context,
625	            slice::from_ref(&resources.path_intermediate_srv),
626	            slice::from_ref(&self.globals.sampler),
627	            sprites.len() as u32,
628	        )
629	    }
