726	    pub(crate) fn gpu_specs(&self) -> Result<GpuSpecs> {
727	        let devices = self.devices.as_ref().context("devices missing")?;
728	        let desc = unsafe { devices.adapter.GetDesc1() }?;
729	        let is_software_emulated = (desc.Flags & DXGI_ADAPTER_FLAG_SOFTWARE.0 as u32) != 0;
730	        let device_name = String::from_utf16_lossy(&desc.Description)
731	            .trim_matches(char::from(0))
732	            .to_string();
733	        let driver_name = match desc.VendorId {
734	            0x10DE => "NVIDIA Corporation".to_string(),
735	            0x1002 => "AMD Corporation".to_string(),
736	            0x8086 => "Intel Corporation".to_string(),
737	            id => format!("Unknown Vendor (ID: {:#X})", id),
738	        };
739	        let driver_version = match desc.VendorId {
740	            0x10DE => nvidia::get_driver_version(),
741	            0x1002 => amd::get_driver_version(),
742	            // For Intel and other vendors, we use the DXGI API to get the driver version.
743	            _ => dxgi::get_driver_version(&devices.adapter),
744	        }
745	        .context("Failed to get gpu driver info")
746	        .log_err()
747	        .unwrap_or("Unknown Driver".to_string());
748	        Ok(GpuSpecs {
749	            is_software_emulated,
750	            device_name,
751	            driver_name,
752	            driver_info: driver_version,
753	        })
754	    }
