756	    pub(crate) fn get_font_info() -> &'static FontInfo {
757	        static CACHED_FONT_INFO: OnceLock<FontInfo> = OnceLock::new();
758	        CACHED_FONT_INFO.get_or_init(|| unsafe {
759	            let factory: IDWriteFactory5 = DWriteCreateFactory(DWRITE_FACTORY_TYPE_SHARED).unwrap();
760	            let render_params: IDWriteRenderingParams1 =
761	                factory.CreateRenderingParams().unwrap().cast().unwrap();
762	            FontInfo {
763	                gamma_ratios: gpui::get_gamma_correction_ratios(render_params.GetGamma()),
764	                grayscale_enhanced_contrast: render_params.GetGrayscaleEnhancedContrast(),
765	                subpixel_enhanced_contrast: render_params.GetEnhancedContrast(),
766	                is_bgr: render_params.GetPixelGeometry() == DWRITE_PIXEL_GEOMETRY_BGR,
767	            }
768	        })
769	    }
