991	struct PipelineState<T> {
992	    label: &'static str,
993	    vertex: ID3D11VertexShader,
994	    fragment: ID3D11PixelShader,
995	    buffer: ID3D11Buffer,
996	    buffer_size: usize,
997	    view: Option<ID3D11ShaderResourceView>,
998	    blend_state: ID3D11BlendState,
999	    _marker: std::marker::PhantomData<T>,
1000	}
