1002	impl<T> PipelineState<T> {
1003	    fn new(
1004	        device: &ID3D11Device,
1005	        label: &'static str,
1006	        shader_module: ShaderModule,
1007	        buffer_size: usize,
1008	        blend_state: ID3D11BlendState,
1009	    ) -> Result<Self> {
1010	        let vertex = {
1011	            let raw_shader = RawShaderBytes::new(shader_module, ShaderTarget::Vertex)?;
1012	            create_vertex_shader(device, raw_shader.as_bytes())?
1013	        };
1014	        let fragment = {
1015	            let raw_shader = RawShaderBytes::new(shader_module, ShaderTarget::Fragment)?;
1016	            create_fragment_shader(device, raw_shader.as_bytes())?
1017	        };
1018	        let buffer = create_buffer(device, std::mem::size_of::<T>(), buffer_size)?;
1019	        let view = create_buffer_view(device, &buffer)?;
1020	
1021	        Ok(PipelineState {
1022	            label,
1023	            vertex,
1024	            fragment,
1025	            buffer,
1026	            buffer_size,
1027	            view,
1028	            blend_state,
1029	            _marker: std::marker::PhantomData,
1030	        })
1031	    }
1032	
1033	    fn update_buffer(
1034	        &mut self,
1035	        device: &ID3D11Device,
1036	        device_context: &ID3D11DeviceContext,
1037	        data: &[T],
1038	    ) -> Result<()> {
1039	        if self.buffer_size < data.len() {
1040	            let element_size = std::mem::size_of::<T>();
1041	            let required_size = std::mem::size_of_val(data);
1042	            anyhow::ensure!(
1043	                required_size <= MAX_INSTANCE_BUFFER_SIZE,
1044	                "{} buffer needs {required_size} bytes, above the maximum of {MAX_INSTANCE_BUFFER_SIZE}",
1045	                self.label
1046	            );
1047	            let new_buffer_size = data
1048	                .len()
1049	                .next_power_of_two()
1050	                .min(MAX_INSTANCE_BUFFER_SIZE / element_size);
1051	            log::debug!(
1052	                "Updating {} buffer size from {} to {}",
1053	                self.label,
1054	                self.buffer_size,
1055	                new_buffer_size
1056	            );
1057	            let buffer = create_buffer(device, std::mem::size_of::<T>(), new_buffer_size)?;
1058	            let view = create_buffer_view(device, &buffer)?;
1059	            self.buffer = buffer;
1060	            self.view = view;
1061	            self.buffer_size = new_buffer_size;
1062	        }
1063	        update_buffer(device_context, &self.buffer, data)
1064	    }
