1705	    #[cfg(debug_assertions)]
1706	    pub(super) fn build_shader_blob(entry: ShaderModule, target: ShaderTarget) -> Result<ID3DBlob> {
1707	        unsafe {
1708	            use windows::Win32::Graphics::{
1709	                Direct3D::ID3DInclude, Hlsl::D3D_COMPILE_STANDARD_FILE_INCLUDE,
1710	            };
1711	
1712	            let shader_name = if matches!(entry, ShaderModule::EmojiRasterization) {
1713	                "color_text_raster.hlsl"
1714	            } else {
1715	                "shaders.hlsl"
1716	            };
1717	
1718	            let entry = format!(
1719	                "{}_{}\0",
1720	                entry.as_str(),
1721	                match target {
1722	                    ShaderTarget::Vertex => "vertex",
1723	                    ShaderTarget::Fragment => "fragment",
1724	                }
1725	            );
1726	            let target = match target {
1727	                ShaderTarget::Vertex => "vs_4_1\0",
1728	                ShaderTarget::Fragment => "ps_4_1\0",
1729	            };
1730	
1731	            let mut compile_blob = None;
1732	            let mut error_blob = None;
1733	            let shader_path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
1734	                .join(&format!("src/{}", shader_name))
1735	                .canonicalize()?;
1736	
1737	            let entry_point = PCSTR::from_raw(entry.as_ptr());
1738	            let target_cstr = PCSTR::from_raw(target.as_ptr());
1739	
1740	            // really dirty trick because winapi bindings are unhappy otherwise
1741	            let include_handler = &std::mem::transmute::<usize, ID3DInclude>(
1742	                D3D_COMPILE_STANDARD_FILE_INCLUDE as usize,
1743	            );
1744	
1745	            let ret = D3DCompileFromFile(
1746	                &HSTRING::from(shader_path.to_str().unwrap()),
1747	                None,
1748	                include_handler,
1749	                entry_point,
1750	                target_cstr,
1751	                D3DCOMPILE_DEBUG | D3DCOMPILE_SKIP_OPTIMIZATION,
1752	                0,
1753	                &mut compile_blob,
1754	                Some(&mut error_blob),
1755	            );
1756	            if ret.is_err() {
1757	                let Some(error_blob) = error_blob else {
1758	                    return Err(anyhow::anyhow!("{ret:?}"));
1759	                };
1760	
1761	                let error_string =
1762	                    std::ffi::CStr::from_ptr(error_blob.GetBufferPointer() as *const i8)
1763	                        .to_string_lossy();
1764	                log::error!("Shader compile error: {}", error_string);
1765	                return Err(anyhow::anyhow!("Compile error: {}", error_string));
1766	            }
1767	            Ok(compile_blob.unwrap())
1768	        }
1769	    }
