1792	mod nvidia {
1793	    use std::{
1794	        ffi::CStr,
1795	        os::raw::{c_char, c_int, c_uint},
1796	    };
1797	
1798	    use anyhow::Result;
1799	    use windows::{Win32::System::LibraryLoader::GetProcAddress, core::s};
1800	
1801	    use crate::with_dll_library;
1802	
1803	    // https://github.com/NVIDIA/nvapi/blob/7cb76fce2f52de818b3da497af646af1ec16ce27/nvapi_lite_common.h#L180
1804	    const NVAPI_SHORT_STRING_MAX: usize = 64;
1805	
1806	    // https://github.com/NVIDIA/nvapi/blob/7cb76fce2f52de818b3da497af646af1ec16ce27/nvapi_lite_common.h#L235
1807	    #[allow(non_camel_case_types)]
1808	    type NvAPI_ShortString = [c_char; NVAPI_SHORT_STRING_MAX];
1809	
1810	    // https://github.com/NVIDIA/nvapi/blob/7cb76fce2f52de818b3da497af646af1ec16ce27/nvapi_lite_common.h#L447
1811	    #[allow(non_camel_case_types)]
1812	    type NvAPI_SYS_GetDriverAndBranchVersion_t = unsafe extern "C" fn(
1813	        driver_version: *mut c_uint,
1814	        build_branch_string: *mut NvAPI_ShortString,
1815	    ) -> c_int;
1816	
1817	    pub(super) fn get_driver_version() -> Result<String> {
1818	        #[cfg(target_pointer_width = "64")]
1819	        let nvidia_dll_name = s!("nvapi64.dll");
1820	        #[cfg(target_pointer_width = "32")]
1821	        let nvidia_dll_name = s!("nvapi.dll");
1822	
1823	        with_dll_library(nvidia_dll_name, |nvidia_dll| unsafe {
1824	            let nvapi_query_addr = GetProcAddress(nvidia_dll, s!("nvapi_QueryInterface"))
1825	                .ok_or_else(|| anyhow::anyhow!("Failed to get nvapi_QueryInterface address"))?;
1826	            let nvapi_query: extern "C" fn(u32) -> *mut () = std::mem::transmute(nvapi_query_addr);
1827	
1828	            // https://github.com/NVIDIA/nvapi/blob/7cb76fce2f52de818b3da497af646af1ec16ce27/nvapi_interface.h#L41
1829	            let nvapi_get_driver_version_ptr = nvapi_query(0x2926aaad);
1830	            if nvapi_get_driver_version_ptr.is_null() {
1831	                anyhow::bail!("Failed to get NVIDIA driver version function pointer");
1832	            }
1833	            let nvapi_get_driver_version: NvAPI_SYS_GetDriverAndBranchVersion_t =
1834	                std::mem::transmute(nvapi_get_driver_version_ptr);
1835	
1836	            let mut driver_version: c_uint = 0;
1837	            let mut build_branch_string: NvAPI_ShortString = [0; NVAPI_SHORT_STRING_MAX];
1838	            let result = nvapi_get_driver_version(
1839	                &mut driver_version as *mut c_uint,
1840	                &mut build_branch_string as *mut NvAPI_ShortString,
1841	            );
1842	
1843	            if result != 0 {
1844	                anyhow::bail!(
1845	                    "Failed to get NVIDIA driver version, error code: {}",
1846	                    result
1847	                );
1848	            }
1849	            let major = driver_version / 100;
1850	            let minor = driver_version % 100;
1851	            let branch_string = CStr::from_ptr(build_branch_string.as_ptr());
1852	            Ok(format!(
1853	                "{}.{} {}",
1854	                major,
1855	                minor,
1856	                branch_string.to_string_lossy()
1857	            ))
1858	        })
1859	    }
1860	}
