1871	    const AGS_CURRENT_VERSION: i32 = (6 << 22) | (3 << 12);
1872	
1873	    // https://github.com/GPUOpen-LibrariesAndSDKs/AGS_SDK/blob/5d8812d703d0335741b6f7ffc37838eeb8b967f7/ags_lib/inc/amd_ags.h#L204
1874	    // This is an opaque type, using struct to represent it properly for FFI
1875	    #[repr(C)]
1876	    struct AGSContext {
1877	        _private: [u8; 0],
1878	    }
1879	
1880	    #[repr(C)]
1881	    pub struct AGSGPUInfo {
1882	        pub driver_version: *const c_char,
1883	        pub radeon_software_version: *const c_char,
1884	        pub num_devices: c_int,
1885	        pub devices: *mut c_void,
1886	    }
1887	
1888	    // https://github.com/GPUOpen-LibrariesAndSDKs/AGS_SDK/blob/5d8812d703d0335741b6f7ffc37838eeb8b967f7/ags_lib/inc/amd_ags.h#L429
1889	    #[allow(non_camel_case_types)]
1890	    type agsInitialize_t = unsafe extern "C" fn(
1891	        version: c_int,
1892	        config: *const c_void,
1893	        context: *mut *mut AGSContext,
1894	        gpu_info: *mut AGSGPUInfo,
1895	    ) -> c_int;
1896	
1897	    // https://github.com/GPUOpen-LibrariesAndSDKs/AGS_SDK/blob/5d8812d703d0335741b6f7ffc37838eeb8b967f7/ags_lib/inc/amd_ags.h#L436
1898	    #[allow(non_camel_case_types)]
1899	    type agsDeInitialize_t = unsafe extern "C" fn(context: *mut AGSContext) -> c_int;
1900	
1901	    pub(super) fn get_driver_version() -> Result<String> {
1902	        #[cfg(target_pointer_width = "64")]
1903	        let amd_dll_name = s!("amd_ags_x64.dll");
1904	        #[cfg(target_pointer_width = "32")]
1905	        let amd_dll_name = s!("amd_ags_x86.dll");
1906	
1907	        with_dll_library(amd_dll_name, |amd_dll| unsafe {
1908	            let ags_initialize_addr = GetProcAddress(amd_dll, s!("agsInitialize"))
1909	                .ok_or_else(|| anyhow::anyhow!("Failed to get agsInitialize address"))?;
1910	            let ags_deinitialize_addr = GetProcAddress(amd_dll, s!("agsDeInitialize"))
1911	                .ok_or_else(|| anyhow::anyhow!("Failed to get agsDeInitialize address"))?;
1912	
1913	            let ags_initialize: agsInitialize_t = std::mem::transmute(ags_initialize_addr);
1914	            let ags_deinitialize: agsDeInitialize_t = std::mem::transmute(ags_deinitialize_addr);
1915	
1916	            let mut context: *mut AGSContext = std::ptr::null_mut();
1917	            let mut gpu_info: AGSGPUInfo = AGSGPUInfo {
1918	                driver_version: std::ptr::null(),
1919	                radeon_software_version: std::ptr::null(),
1920	                num_devices: 0,
1921	                devices: std::ptr::null_mut(),
1922	            };
1923	
1924	            let result = ags_initialize(
1925	                AGS_CURRENT_VERSION,
1926	                std::ptr::null(),
1927	                &mut context,
1928	                &mut gpu_info,
1929	            );
1930	            if result != 0 {
1931	                anyhow::bail!("Failed to initialize AMD AGS, error code: {}", result);
1932	            }
1933	
1934	            // Vulkan actually returns this as the driver version
1935	            let software_version = if !gpu_info.radeon_software_version.is_null() {
1936	                std::ffi::CStr::from_ptr(gpu_info.radeon_software_version)
1937	                    .to_string_lossy()
1938	                    .into_owned()
1939	            } else {
1940	                "Unknown Radeon Software Version".to_string()
1941	            };
1942	
1943	            let driver_version = if !gpu_info.driver_version.is_null() {
1944	                std::ffi::CStr::from_ptr(gpu_info.driver_version)
1945	                    .to_string_lossy()
1946	                    .into_owned()
1947	            } else {
1948	                "Unknown Radeon Driver Version".to_string()
1949	            };
1950	
1951	            ags_deinitialize(context);
1952	            Ok(format!("{} ({})", software_version, driver_version))
1953	        })
1954	    }
1955	}
